import React, { useState, useEffect, useRef } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const NhanTinCuDan = () => {
    const [tabActive, setTabActive] = useState('all');
    const [message, setMessage] = useState('');
    const [userRoom, setUserRoom] = useState('');

    // Lấy thông tin phòng của cư dân hiện tại
    useEffect(() => {
        const savedProfile = localStorage.getItem('userProfile');
        if (savedProfile) {
            const profile = JSON.parse(savedProfile);
            setUserRoom(profile.room_id || profile.room || 'Resident');
        }
    }, []);

    const [chatHistory, setChatHistory] = useState(() => {
        const savedChat = localStorage.getItem('chatHistory');
        return savedChat ? JSON.parse(savedChat) : [];
    });

    const chatEndRef = useRef(null);

    const scrollToBottom = () => {
        chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        localStorage.setItem('chatHistory', JSON.stringify(chatHistory));
        scrollToBottom();
    }, [chatHistory, tabActive]);

    const handleSendMessage = (type) => {
        if (message.trim() === '') return;

        const newMessage = {
            id: Date.now(),
            sender: userRoom, // Gửi bằng số phòng của cư dân
            content: message,
            type: type, 
            // Nếu gửi private, target mặc định là Admin (AD)
            target: type === 'all' ? 'Tất cả' : 'AD',
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            fullTimestamp: new Date().toISOString()
        };

        setChatHistory([...chatHistory, newMessage]);
        setMessage('');
    };

    const renderMessageList = (type) => {
        // Lọc tin nhắn: 
        // 1. Nếu là 'all': Hiện tất cả tin nhắn type 'all'
        // 2. Nếu là 'private': Chỉ hiện tin nhắn giữa userRoom này và Admin (AD)
        const filteredChats = chatHistory.filter(m => {
            if (type === 'all') return m.type === 'all';
            return m.type === 'private' && (
                (m.sender === userRoom && m.target === 'AD') || 
                (m.sender === 'AD' && m.target.includes(userRoom))
            );
        });

        return filteredChats.map((msg, index) => {
            const isMe = msg.sender === userRoom;
            const prevMsg = filteredChats[index - 1];
            const isSameSenderAsPrev = prevMsg && prevMsg.sender === msg.sender;

            return (
                <div key={msg.id} style={{ 
                    display: 'flex', 
                    flexDirection: 'column',
                    alignItems: isMe ? 'flex-end' : 'flex-start',
                    marginBottom: isSameSenderAsPrev ? '4px' : '20px',
                    marginTop: isSameSenderAsPrev ? '0px' : '10px'
                }}>
                    {!isSameSenderAsPrev && (
                        <span style={{ fontSize: '11px', color: '#fff', marginBottom: '4px', opacity: 0.8 }}>
                            {isMe ? "Bạn" : (msg.sender === 'AD' ? "Ban Quản Lý" : `Phòng ${msg.sender}`)}
                        </span>
                    )}
                    <div style={{ 
                        display: 'flex', 
                        flexDirection: isMe ? 'row-reverse' : 'row', 
                        alignItems: 'flex-end',
                        gap: '10px',
                        maxWidth: '85%'
                    }}>
                        <div style={{ 
                            backgroundColor: isMe ? 'rgba(30, 30, 30, 0.95)' : '#fff', 
                            padding: '12px 18px',
                            borderRadius: isMe 
                                ? (isSameSenderAsPrev ? '18px 6px 18px 18px' : '18px 18px 6px 18px') 
                                : (isSameSenderAsPrev ? '6px 18px 18px 18px' : '18px 18px 18px 6px'), 
                            fontSize: '15px',
                            color: isMe ? '#fff' : '#000',
                            boxShadow: '0 3px 10px rgba(0,0,0,0.1)'
                        }}>
                            {msg.content}
                            <div style={{ fontSize: '9px', opacity: 0.5, marginTop: '5px', textAlign: 'right' }}>
                                {msg.time}
                            </div>
                        </div>
                    </div>
                </div>
            );
        });
    };

    return (
        <div style={containerStyle} className="glass-card">

            {/* Header Tabs - Chỉ có Nhóm chung và Admin */}
            <div style={headerStyle}>
                <button onClick={() => setTabActive('all')} style={{ 
                    ...tabBtnStyle, 
                    backgroundColor: tabActive === 'all' ? '#fff' : 'rgba(255,255,255,0.2)',
                    color: tabActive === 'all' ? '#333' : '#fff'
                }}>
                    💬 Nhóm chung cư dân
                </button>
                <button onClick={() => setTabActive('private')} style={{ 
                    ...tabBtnStyle, 
                    backgroundColor: tabActive === 'private' ? '#8b5e5e' : 'rgba(255,255,255,0.2)',
                    color: '#fff'
                }}>
                    🛡️ Chat với Admin
                </button>
                <div style={roomBadge}>Phòng: {userRoom}</div>
            </div>

            {/* Chat Area */}
            <div style={{ flex: 1, padding: '20px', display: 'flex', flexDirection: 'column', minHeight: 0 }}>
                <div style={{ flex: 1, overflowY: 'auto', paddingRight: '10px' }} className="custom-scrollbar">
                    {renderMessageList(tabActive)}
                    <div ref={chatEndRef} />
                </div>

                {/* Input Area */}
                <div style={inputContainer}>
                    <input 
                        style={inputStyle} 
                        placeholder={tabActive === 'all' ? "Nhắn tin cho cả tòa nhà..." : "Gửi tin nhắn riêng cho Ban quản lý..."} 
                        value={message} 
                        onChange={(e) => setMessage(e.target.value)} 
                        onKeyPress={(e) => e.key === 'Enter' && handleSendMessage(tabActive)} 
                    />
                    <button onClick={() => handleSendMessage(tabActive)} style={sendBtnStyle}>
                        ➤
                    </button>
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.3); border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- STYLES ---
const containerStyle = { flex: 1, display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', borderRadius: '30px', overflow: 'hidden', height: 'calc(100vh - 120px)' };
const headerStyle = { padding: '20px', display: 'flex', gap: '15px', background: 'rgba(0,0,0,0.3)', alignItems: 'center' };
const tabBtnStyle = { padding: '10px 20px', borderRadius: '20px', border: 'none', fontWeight: 'bold', cursor: 'pointer', transition: '0.3s', fontSize: '14px' };
const roomBadge = { marginLeft: 'auto', color: '#fff', background: 'rgba(255,255,255,0.1)', padding: '8px 15px', borderRadius: '12px', fontSize: '13px', fontWeight: 'bold', border: '1px solid rgba(255,255,255,0.2)' };
const inputContainer = { display: 'flex', gap: '12px', paddingTop: '15px' };
const inputStyle = { flex: 1, padding: '15px 25px', borderRadius: '25px', border: 'none', outline: 'none', fontSize: '15px', backgroundColor: '#fff', boxShadow: '0 4px 15px rgba(0,0,0,0.2)' };
const sendBtnStyle = { width: '50px', height: '50px', borderRadius: '50%', border: 'none', backgroundColor: '#333', color: '#fff', fontSize: '18px', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' };

export default NhanTinCuDan;
